import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:openvalut/openvalut_cloud/openvalut_crypto.dart';

Uint8List _hex(String s) => Uint8List.fromList(
  List.generate(
    s.length ~/ 2,
    (i) => int.parse(s.substring(i * 2, i * 2 + 2), radix: 16),
  ),
);

String _toHex(List<int> bytes) =>
    [for (final b in bytes) b.toRadixString(16).padLeft(2, '0')].join();

// Vectors generated by server/internal/crypto (Go): recipient X25519 keypair,
// a random share key, and the wrapped share key (ephemeral pub || nonce ||
// ciphertext).
const _goPriv =
    '9a5d3e1f878ef41c159eac16b0c85268cc51d63a69189e4718ccd188fab7ea57';
const _goPub =
    '35405b02ac59d68550c63b07d0a0900602e1f5541620ba8fd35951c76c99aa39';
const _goShareKey =
    '57966b2abf0b4e22cfa2c4e4c0db44d655818cba8069bfb6c7ef30a8803e35df';
const _goWrapped =
    '7cea0fdeaee8f3ff9be68a0a240c7693906d0778314b86cc29450e733e61ea37'
    '87061e25f4b6689a2d68a90258369eba858d26722622371f869048847eddfc8d'
    '2e2901f725bd35058bfa5128676af4b7a8cef2118947589e9c902647';

void main() {
  test('Dart unwraps a Go-wrapped share key', () async {
    final shareKey = await openvalutCrypto.unwrapShareKey(
      privateKey: _hex(_goPriv),
      wrapped: _hex(_goWrapped),
    );
    expect(_toHex(shareKey), _goShareKey);
  });

  test('Dart wraps a share key that Go can unwrap', () async {
    final shareKey = _hex(_goShareKey);
    final wrapped = await openvalutCrypto.wrapShareKey(
      recipientPublicKey: _hex(_goPub),
      shareKey: shareKey,
    );
    // Layout: 32-byte ephemeral pubkey || 12-byte nonce || ciphertext+tag.
    expect(wrapped.length, 32 + 12 + 32 + 16);
    print('DART_WRAPPED=${_toHex(wrapped)}');
  });

  test('share identity round-trips via private key bytes', () async {
    final identity = await openvalutCrypto.generateShareIdentity();
    expect(identity.privateKey.length, 32);
    expect(identity.publicKey.length, 32);

    final other = await openvalutCrypto.generateShareIdentity();
    final shareKey = _hex(_goShareKey);
    final wrapped = await openvalutCrypto.wrapShareKey(
      recipientPublicKey: other.publicKey,
      shareKey: shareKey,
    );
    final unwrapped = await openvalutCrypto.unwrapShareKey(
      privateKey: other.privateKey,
      wrapped: wrapped,
    );
    expect(_toHex(unwrapped), _goShareKey);
  });

  test('shared entry JSON round-trips', () {
    final entry = openvalutSharedEntry(
      fields: {
        'Title': 'GitHub',
        'UserName': 'octocat',
        'Password': 'gh-secret',
        'URL': 'https://github.com',
      },
    );
    final restored = openvalutSharedEntry.fromBytes(entry.toBytes());
    expect(restored.label, 'GitHub');
    expect(restored.username, 'octocat');
    expect(restored.password, 'gh-secret');
    expect(json.decode(utf8.decode(entry.toBytes())), entry.fields);
  });
}
